/**
 * Per-protocol contract flowcharts, generated by `npm run flowcharts:docs`.
 *
 * The committed data lives in `data/contract-flows.json`; `docs/10-contract-flows.md` is rendered
 * from it. The showcase reads the same records so a protocol page cannot draw a different flow
 * from the doc.
 *
 * Everything is optional on purpose: a checkout without the generated file still boots, it just
 * has no diagrams.
 */

let data = null;
try {
  data = require("../../data/contract-flows.json");
} catch {
  data = null;
}

const FLOWS = (data && Array.isArray(data.flows) ? data.flows : []).slice();
const BY_KEY = new Map(FLOWS.map(flow => [flow.key, flow]));

const NODE_KINDS = ["actor", "contract", "token", "external", "offchain"];
const EDGE_KINDS = ["call", "transfer", "event", "offchain"];

/** The flow for a catalog row: the first of its recipe keys that has one. */
function flowForKeys(keys) {
  for (const key of keys || []) {
    const flow = BY_KEY.get(String(key || "").toLowerCase());
    if (flow) return flow;
  }
  return null;
}

module.exports = {
  FLOWS,
  TOTALS: (data && data.totals) || null,
  NODE_KINDS,
  EDGE_KINDS,
  flowForKeys,
};
